<template>
  <div class="deployment-workspace">
    <section class="deploy-config" aria-label="部署模型">
      <div class="pane-heading"><div><h3>部署模型</h3></div><span>local-robot</span></div>
      <div class="target-state" :class="{ healthy: target?.healthy }"><small>本机机器人</small><strong>{{ target?.current ? `${target.current.modelName} v${target.current.modelVersion}` : "尚未部署" }}</strong><span>{{ target?.current ? target.healthy ? "产物指针正常" : "产物指针异常" : "等待选择生产模型" }}</span></div>
      <div class="form-grid"><label>Production 模型<select v-model="form.modelId"><option value="" disabled>选择模型</option><option v-for="model in productionModels" :key="model.id" :value="model.id">{{ model.name }} v{{ model.version }}{{ model.evaluation.successRate == null ? "" : ` · ${formatPercent(model.evaluation.successRate)}` }}</option></select></label><label>操作人<input v-model.trim="form.actor" maxlength="80" /></label><label>部署备注<textarea v-model.trim="form.notes" maxlength="500" rows="3"></textarea></label></div>
      <div v-if="selectedModel" class="model-gate"><div><span>评估任务</span><strong>{{ selectedModel.evaluation.jobs }}</strong></div><div><span>有效 Episodes</span><strong>{{ selectedModel.evaluation.success + selectedModel.evaluation.failure }}</strong></div><div><span>成功率</span><strong>{{ formatPercent(selectedModel.evaluation.successRate) }}</strong></div><ul><li v-for="check in selectedModel.deploymentGate.checks" :key="check.id" :class="{ passed: check.passed }"><i></i><span>{{ check.label }}</span><strong>{{ gateValue(check) }}</strong></li></ul></div>
      <details class="gate-settings"><summary>发布门禁设置</summary><div><label>最少有效 Episodes<input v-model.number="gateForm.minEvaluatedEpisodes" type="number" min="0" max="10000" /></label><label>最低成功率<input v-model.number="gateSuccessPercent" type="number" min="0" max="100" step="1" /></label><label>最低置信下界<input v-model.number="gateConfidencePercent" type="number" min="0" max="100" step="1" /></label><label>异常阻断<select v-model="gateForm.blockOpenSeverity"><option value="error">错误及严重</option><option value="critical">仅严重</option><option value="none">不阻断</option></select></label><button :disabled="savingGate" @click="saveGate">{{ savingGate ? "保存中…" : "保存规则" }}</button></div></details>
      <label v-if="selectedModel && !selectedModel.deploymentGate.ready" class="override-reason">受控放行理由<textarea v-model.trim="form.overrideReason" maxlength="500" rows="2" placeholder="至少 10 个字符，将写入部署修订"></textarea></label>
      <button class="primary" :disabled="deployDisabled" @click="deployModel">{{ deployButtonText }}</button>
      <p class="deploy-hint">部署仅原子切换模型目录，不会启动推理或驱动机械臂。</p>
    </section>

    <section class="revision-pane" aria-label="部署历史">
      <div class="pane-heading"><div><h3>部署历史</h3></div><span>{{ target?.revisions.length || 0 }} 个修订</span></div>
      <div v-if="target?.current" class="current-revision"><div><small>当前修订</small><strong>{{ target.current.id }}</strong></div><span>{{ formatDate(target.current.deployedAt) }} · {{ target.current.deployedBy }}</span><code>{{ target.linkPath }}</code></div>
      <div v-if="target" class="runtime-card" :class="target.runtime.status"><div class="runtime-heading"><span><small>推理运行状态</small><strong>{{ runtimeStatusText(target.runtime.status) }}</strong></span><em>{{ target.runtime.lastHeartbeat ? formatDate(target.runtime.lastHeartbeat) : "暂无心跳" }}</em></div><div class="runtime-stats"><span><small>推理次数</small><strong>{{ target.runtime.inferenceCount }}</strong></span><span><small>错误次数</small><strong>{{ target.runtime.errorCount }}</strong></span><span><small>平均延迟</small><strong>{{ formatLatency(target.runtime.avgLatencyMs) }}</strong></span><span><small>P95 延迟</small><strong>{{ formatLatency(target.runtime.p95LatencyMs) }}</strong></span></div><p v-if="target.runtime.lastError">最近错误：{{ target.runtime.lastError }}</p><small class="runtime-hint">推理进程通过 heartbeat API 上报；30 秒无心跳自动离线。</small></div>
      <div v-if="target?.revisions.length" class="revision-list"><article v-for="revision in target.revisions" :key="revision.id" :class="{ active: revision.status === 'active' }"><div><span><strong>{{ revision.modelName }} v{{ revision.modelVersion }}</strong><small>{{ revision.action === "rollback" ? "回滚部署" : "正常部署" }} · {{ formatDate(revision.deployedAt) }}</small></span><em>{{ revision.status === "active" ? "当前" : "历史" }}</em></div><code :title="revision.sha256">{{ revision.sha256.slice(0, 16) }}…</code><p>{{ revision.notes || "无部署备注" }}</p><p v-if="revision.overrideReason" class="override-record">受控放行：{{ revision.overrideReason }}</p><button v-if="revision.status !== 'active'" :disabled="rollingBack" @click="rollback(revision.id)">回滚到此修订</button></article></div>
      <div v-else class="empty">部署后会在这里保留不可变修订历史</div>
    </section>

    <section class="incident-pane" aria-label="推理异常">
      <div class="pane-heading"><div><h3>推理异常</h3></div><span>{{ openIncidents }} 未关闭</span></div>
      <div class="incident-form"><div><label>严重程度<select v-model="incidentForm.severity"><option value="warning">警告</option><option value="error">错误</option><option value="critical">严重</option></select></label><label>类型<select v-model="incidentForm.category"><option v-for="item in incidentCategories" :key="item.value" :value="item.value">{{ item.label }}</option></select></label></div><label>异常描述<textarea v-model.trim="incidentForm.description" maxlength="1000" rows="3"></textarea></label><button :disabled="!target?.current || !incidentForm.description || reporting" @click="reportIncident">记录异常</button></div>
      <div v-if="incidents.length" class="incident-list"><article v-for="incident in incidents" :key="incident.id" :class="[incident.severity, incident.status]"><header><span><strong>{{ categoryText(incident.category) }}</strong><small>{{ formatDate(incident.reportedAt) }} · {{ incident.reportedBy }}</small></span><em>{{ incident.status === "open" ? severityText(incident.severity) : "已关闭" }}</em></header><p>{{ incident.description }}</p><div v-if="incident.status === 'open'" class="resolve-row"><input v-model.trim="resolutions[incident.id]" maxlength="1000" placeholder="处理结论" /><button :disabled="!resolutions[incident.id]" @click="resolveIncident(incident.id)">关闭</button></div><small v-else class="resolution">处理结论：{{ incident.resolution }}</small></article></div>
      <div v-else class="empty">尚无推理异常记录</div>
    </section>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from "vue";

interface EvaluationMetric { jobs: number; episodes: number; success: number; failure: number; successRate: number | null; confidenceLow: number | null; confidenceHigh: number | null }
interface GateConfig { minEvaluatedEpisodes: number; minSuccessRate: number; minConfidenceLow: number; blockOpenSeverity: "none" | "critical" | "error"; updatedAt: string | null; updatedBy: string }
interface GateCheck { id: "evaluatedEpisodes" | "successRate" | "confidenceLow" | "openIncidents"; label: string; passed: boolean; actual: number; threshold: number | null }
interface GateResult { ready: boolean; checkedAt: string; checks: GateCheck[]; config: GateConfig }
interface Model { id: string; name: string; version: number; stage: string; evaluation: EvaluationMetric; deploymentGate: GateResult }
interface Revision { id: string; modelId: string; modelName: string; modelVersion: number; sha256: string; action: "deploy" | "rollback"; status: "active" | "superseded"; deployedAt: string; deployedBy: string; notes: string; releaseGate?: GateResult | null; overrideReason?: string }
interface Runtime { status: "offline" | "healthy" | "degraded"; lastHeartbeat: string | null; startedAt: string | null; inferenceCount: number; successCount: number; errorCount: number; avgLatencyMs: number | null; p95LatencyMs: number | null; recentLatencies: number[]; lastError: string; processId: string; updatedAt: string | null }
interface Target { id: string; name: string; currentRevisionId: string | null; revisions: Revision[]; current: Revision | null; linkPath: string; healthy: boolean; openIncidents: number; runtime: Runtime }
interface Incident { id: string; targetId: string; revisionId: string | null; modelId: string | null; severity: "warning" | "error" | "critical"; category: string; description: string; status: "open" | "resolved"; reportedAt: string; reportedBy: string; resolvedAt: string | null; resolution: string }

const emit = defineEmits<{ error: [message: string] }>();
const models = ref<Model[]>([]); const targets = ref<Target[]>([]); const incidents = ref<Incident[]>([]); const deploying = ref(false); const rollingBack = ref(false); const reporting = ref(false); const savingGate = ref(false);
const resolutions = reactive<Record<string, string>>({});
const form = reactive({ modelId: "", actor: "本地用户", notes: "", overrideReason: "" });
const gateForm = reactive<GateConfig>({ minEvaluatedEpisodes: 10, minSuccessRate: .8, minConfidenceLow: .5, blockOpenSeverity: "error", updatedAt: null, updatedBy: "" });
const incidentForm = reactive({ severity: "warning" as Incident["severity"], category: "jitter", description: "" });
const incidentCategories = [{ value: "jitter", label: "机械臂抖动" }, { value: "action_offset", label: "动作偏移" }, { value: "collision", label: "碰撞" }, { value: "camera", label: "相机异常" }, { value: "latency", label: "推理延迟" }, { value: "hardware", label: "硬件异常" }, { value: "other", label: "其他" }];
const target = computed(() => targets.value.find((item) => item.id === "local-robot") || null);
const productionModels = computed(() => models.value.filter((model) => model.stage === "production"));
const selectedModel = computed(() => productionModels.value.find((model) => model.id === form.modelId) || productionModels.value[0] || null);
const openIncidents = computed(() => incidents.value.filter((incident) => incident.status === "open").length);
const gateSuccessPercent = computed({ get: () => Math.round(gateForm.minSuccessRate * 100), set: (value: number) => { gateForm.minSuccessRate = Number(value) / 100; } });
const gateConfidencePercent = computed({ get: () => Math.round(gateForm.minConfidenceLow * 100), set: (value: number) => { gateForm.minConfidenceLow = Number(value) / 100; } });
const deployDisabled = computed(() => deploying.value || !selectedModel.value || target.value?.current?.modelId === selectedModel.value.id || (!selectedModel.value.deploymentGate.ready && form.overrideReason.length < 10));
const deployButtonText = computed(() => deploying.value ? "校验并部署中…" : target.value?.current?.modelId === selectedModel.value?.id ? "当前已部署" : selectedModel.value && !selectedModel.value.deploymentGate.ready ? "受控放行并部署" : "部署到本机机器人");
let pollTimer: number | null = null;

async function requestJson(url: string, init?: RequestInit) { const response = await fetch(url, init); const data = await response.json(); if (!response.ok || data.ok === false) throw new Error(data.error || `HTTP ${response.status}`); return data; }
async function refreshAll() { try { const [modelData, deploymentData] = await Promise.all([requestJson("/api/training/models"), requestJson("/api/training/deployments")]); models.value = modelData.models || []; targets.value = deploymentData.targets || []; incidents.value = deploymentData.incidents || []; if (deploymentData.releaseGate) Object.assign(gateForm, deploymentData.releaseGate); if (!form.modelId && productionModels.value.length) form.modelId = productionModels.value[0].id; } catch (cause) { emit("error", cause instanceof Error ? cause.message : String(cause)); } }
async function deployModel() { if (!selectedModel.value || deployDisabled.value) return; deploying.value = true; try { await requestJson("/api/training/deployments/local-robot/deploy", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ modelId: selectedModel.value.id, actor: form.actor, notes: form.notes, overrideReason: form.overrideReason }) }); form.overrideReason = ""; await refreshAll(); } catch (cause) { emit("error", cause instanceof Error ? cause.message : String(cause)); } finally { deploying.value = false; } }
async function saveGate() { savingGate.value = true; try { await requestJson("/api/training/deployment-gate", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...gateForm, actor: form.actor }) }); await refreshAll(); } catch (cause) { emit("error", cause instanceof Error ? cause.message : String(cause)); } finally { savingGate.value = false; } }
async function rollback(revisionId: string) { if (rollingBack.value) return; rollingBack.value = true; try { await requestJson("/api/training/deployments/local-robot/rollback", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ revisionId, actor: form.actor, notes: `回滚到 ${revisionId}` }) }); await refreshAll(); } catch (cause) { emit("error", cause instanceof Error ? cause.message : String(cause)); } finally { rollingBack.value = false; } }
async function reportIncident() { if (!incidentForm.description || reporting.value) return; reporting.value = true; try { await requestJson("/api/training/deployments/local-robot/incidents", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...incidentForm, actor: form.actor }) }); incidentForm.description = ""; await refreshAll(); } catch (cause) { emit("error", cause instanceof Error ? cause.message : String(cause)); } finally { reporting.value = false; } }
async function resolveIncident(id: string) { try { await requestJson(`/api/training/incidents/${encodeURIComponent(id)}/resolve`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ resolution: resolutions[id] }) }); resolutions[id] = ""; await refreshAll(); } catch (cause) { emit("error", cause instanceof Error ? cause.message : String(cause)); } }
function formatPercent(value: number | null) { return value == null ? "-" : `${(value * 100).toFixed(1)}%`; }
function formatDate(value: string) { return new Intl.DateTimeFormat("zh-CN", { month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }).format(new Date(value)); }
function categoryText(category: string) { return incidentCategories.find((item) => item.value === category)?.label || category; }
function severityText(severity: Incident["severity"]) { return ({ warning: "警告", error: "错误", critical: "严重" })[severity]; }
function gateValue(check: GateCheck) { if (check.id === "evaluatedEpisodes" || check.id === "openIncidents") return `${check.actual} / ${check.threshold}`; return `${formatPercent(check.actual)} / ${formatPercent(check.threshold)}`; }
function runtimeStatusText(status: Runtime["status"]) { return ({ offline: "离线", healthy: "在线", degraded: "降级" })[status]; }
function formatLatency(value: number | null) { return value == null ? "-" : `${value.toFixed(1)} ms`; }
onMounted(() => { void refreshAll(); pollTimer = window.setInterval(() => { void refreshAll(); }, 5000); });
onUnmounted(() => { if (pollTimer !== null) window.clearInterval(pollTimer); });
</script>

<style scoped>
