1/-1; margin: 0; padding: 4px 8px; border-top: 1px solid rgba(151,188,222,.08); list-style: none; }.model-gate li { display: grid; grid-template-columns: 6px 1fr auto; align-items: center; gap: 5px; min-height: 22px; }.model-gate li i { width: 5px; height: 5px; border-radius: 50%; background: #e8798a; }.model-gate li.passed i { background: #54c994; }.model-gate li strong { color: #8197a7; font-size: 7px; }.gate-settings { margin-top: 8px; border: 1px solid rgba(151,188,222,.12); background: #0b1724; }.gate-settings summary { padding: 8px; cursor: pointer; color: #7891a3; font-size: 8px; }.gate-settings > div { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; padding: 0 8px 8px; }.gate-settings button { grid-column: 1/-1; padding: 7px; border: 1px solid #38536a; border-radius: 3px; cursor: pointer; background: #13283a; color: #94c7da; font-size: 8px; }.override-reason { margin-top: 8px; color: #d6ac67; }.override-reason textarea { border-color: #725a32; }.primary,.incident-form > button { width: 100%; margin-top: 10px; padding: 9px; border: 0; border-radius: 4px; cursor: pointer; background: #64c9e8; color: #07131c; font-size: 9px; font-weight: 650; }.primary:disabled,.incident-form button:disabled { cursor: not-allowed; opacity: .4; }.deploy-hint { color: #60798b; font-size: 8px; line-height: 1.5; }
.current-revision { display: grid; grid-template-columns: 1fr auto; gap: 5px 12px; padding: 10px; border-left: 3px solid #54c994; background: #10251f; }.current-revision div { display: grid; gap: 3px; }.current-revision small,.current-revision span,.current-revision code { color: #718e80; font-size: 7px; }.current-revision strong { color: #b9dac8; font-size: 10px; }.current-revision code { grid-column: 1/-1; overflow-wrap: anywhere; }.revision-list { margin-top: 10px; }.revision-list article { position: relative; padding: 10px; border: 1px solid rgba(151,188,222,.11); border-bottom: 0; background: #091522; }.revision-list article:last-child { border-bottom: 1px solid rgba(151,188,222,.11); }.revision-list article.active { border-left: 3px solid #54c994; }.revision-list article > div { display: flex; justify-content: space-between; gap: 8px; }.revision-list article span { display: grid; gap: 3px; }.revision-list article strong { color: #b7c9d4; font-size: 9px; }.revision-list article small,.revision-list article code,.revision-list article p { color: #657e91; font-size: 7px; }.revision-list article em { padding: 3px 5px; border-radius: 3px; color: #8196a5; background: #263541; font-size: 7px; font-style: normal; }.revision-list article.active em { color: #65daa4; background: #173a31; }.revision-list article code { display: block; margin-top: 7px; }.revision-list article p { margin: 5px 0; }.revision-list article .override-record { padding: 5px; border-left: 2px solid #d6a957; background: #231e14; color: #c8a96d; }.revision-list article > button { padding: 5px 7px; border: 1px solid #38536a; border-radius: 3px; cursor: pointer; background: #101f2e; color: #8fc8dc; font-size: 7px; }
.runtime-card { display: grid; gap: 8px; margin-top: 10px; padding: 10px; border-left: 3px solid #708394; background: #101c29; }.runtime-card.healthy { border-color: #54c994; background: #10251f; }.runtime-card.degraded { border-color: #e1bf76; background: #272116; }.runtime-card.offline { border-color: #708394; }.runtime-heading { display: flex; justify-content: space-between; gap: 8px; }.runtime-heading span { display: grid; gap: 3px; }.runtime-heading small,.runtime-heading em,.runtime-hint,.runtime-card p { color: #71899a; font-size: 7px; }.runtime-heading strong { color: #bfd1d9; font-size: 10px; }.runtime-card.healthy .runtime-heading strong { color: #76dbaa; }.runtime-card.degraded .runtime-heading strong { color: #e1bf76; }.runtime-heading em { font-style: normal; }.runtime-stats { display: grid; grid-template-columns: 1fr 1fr; border-top: 1px solid rgba(151,188,222,.1); border-bottom: 1px solid rgba(151,188,222,.1); }.runtime-stats span { display: grid; gap: 3px; padding: 7px 4px; }.runtime-stats small { color: #6b8394; font-size: 7px; }.runtime-stats strong { color: #c1d1d8; font: 9px ui-monospace,monospace; }.runtime-card p { margin: 0; color: #d09b8e; line-height: 1.5; }
.incident-form { padding: 10px; border: 1px solid rgba(151,188,222,.12); background: #091522; }.incident-form > div { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin-bottom: 8px; }.incident-list { margin-top: 10px; }.incident-list article { padding: 9px; border: 1px solid rgba(151,188,222,.1); border-left: 3px solid #e1bf76; border-bottom: 0; background: #091522; }.incident-list article:last-child { border-bottom: 1px solid rgba(151,188,222,.1); }.incident-list article.error { border-left-color: #e8798a; }.incident-list article.critical { border-left-color: #ff536a; background: #1e1117; }.incident-list article.resolved { border-left-color: #637686; opacity: .78; }.incident-list header { display: flex; justify-content: space-between; gap: 8px; }.incident-list header span { display: grid; gap: 3px; }.incident-list strong { color: #b8c9d3; font-size: 9px; }.incident-list small,.incident-list p { color: #698194; font-size: 7px; }.incident-list em { padding: 3px 5px; border-radius: 3px; color: #e1bf76; background: #382f1d; font-size: 7px; font-style: normal; }.incident-list article.error em,.incident-list article.critical em { color: #ff91a0; background: #3a2028; }.incident-list p { margin: 7px 0; line-height: 1.5; }.resolve-row { display: grid; grid-template-columns: 1fr auto; gap: 5px; }.resolve-row input { padding: 6px; font-size: 8px; }.resolve-row button { border: 0; border-radius: 3px; cursor: pointer; background: #294b60; color: #b5d6e5; font-size: 8px; }.resolution { display: block; padding-top: 5px; border-top: 1px solid rgba(151,188,222,.08); }.empty { display: grid; place-items: center; min-height: 180px; color: #667f92; font-size: 9px; }
@container (max-width: 1150px) { .deployment-workspace { grid-template-columns: 300px 1fr; }.deploy-config { grid-row: 1/span 2; }.revision-pane { border-right: 0; border-bottom: 1px solid rgba(151,188,222,.13); }.incident-pane { grid-column: 2; } }
@container (max-width: 720px) { .deployment-workspace { display: block; }.deploy-config,.revision-pane { border-right: 0; border-bottom: 1px solid rgba(151,188,222,.13); }.model-gate { grid-template-columns: 1fr 1fr 1fr; } }
/* Light operational theme shared with capture and data management. */
.deployment-workspace { background:#fff; border-color:#dedfe0; }.deploy-config,.revision-pane { border-color:#e2e3e4; }.pane-heading h3 { color:#303235; }.pane-heading > span,.form-grid label,.incident-form label,.override-reason,.gate-settings label { color:#73777b; }.form-grid input,.form-grid select,.form-grid textarea,.incident-form input,.incident-form select,.incident-form textarea,.resolve-row input,.override-reason textarea,.gate-settings input,.gate-settings select { border-color:#d7d9db; background:#fff; color:#3d4144; }.target-state,.runtime-card { background:#f4f6f7; }.target-state.healthy,.runtime-card.healthy,.current-revision { background:#eef8f2; }.target-state small,.target-state span,.runtime-heading small,.runtime-heading em,.runtime-hint,.runtime-card p { color:#73787b; }.target-state strong,.runtime-heading strong,.current-revision strong { color:#34383b; }.gate-settings,.revision-list article,.incident-form,.incident-list article { border-color:#e0e2e3; background:#fff; }.primary,.incident-form > button { background:#3f78d1; color:#fff; }.revision-list article strong,.incident-list strong { color:#3f4346; }.revision-list article small,.revision-list article code,.revision-list article p,.incident-list small,.incident-list p { color:#777c80; }.revision-list article > button,.gate-settings button,.resolve-row button { border-color:#d5d8db; background:#fff; color:#3d72ca; }.incident-list article.critical { background:#fff3f4; }.empty { color:#8c9093; }
.model-gate,.runtime-stats { border-color:#e1e3e4; }.model-gate span,.model-gate strong,.model-gate li strong,.runtime-stats small,.runtime-stats strong { color:#5d6368; }.model-gate li,.runtime-stats { border-color:#e5e6e7; }.gate-settings summary { color:#676d72; }.revision-list article.active { border-left-color:#4b7dd2; }.revision-list article.active em { background:#e7f6ed; color:#32845f; }.revision-list article .override-record { border-color:#dea64b; background:#fff7e9; color:#8b651f; }.runtime-card.degraded { background:#fff7e9; border-color:#dea64b; }.runtime-card.degraded .runtime-heading strong { color:#8b651f; }.incident-list article.error { border-left-color:#df6b70; }.incident-list article.resolved { border-left-color:#8c9195; }
